const ZOOM_SECRET = 'YOUR_ZOOM_WEBHOOK_SECRET_TOKEN';
// =========================================================

function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }
function sha256(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
  const msg = bytes.slice();
  const lenBits = msg.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  const hi = Math.floor(lenBits / 0x100000000);
  const lo = lenBits >>> 0;
  msg.push((hi>>>24)&255,(hi>>>16)&255,(hi>>>8)&255,hi&255,(lo>>>24)&255,(lo>>>16)&255,(lo>>>8)&255,lo&255);
  for (let i=0;i<msg.length;i+=64){
    const w = new Array(64);
    for (let t=0;t<16;t++){ w[t]=((msg[i+t*4]<<24)|(msg[i+t*4+1]<<16)|(msg[i+t*4+2]<<8)|(msg[i+t*4+3]))>>>0; }
    for (let t=16;t<64;t++){
      const s0=rotr(w[t-15],7)^rotr(w[t-15],18)^(w[t-15]>>>3);
      const s1=rotr(w[t-2],17)^rotr(w[t-2],19)^(w[t-2]>>>10);
      w[t]=(w[t-16]+s0+w[t-7]+s1)>>>0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let t=0;t<64;t++){
      const S1=rotr(e,6)^rotr(e,11)^rotr(e,25);
      const ch=(e&f)^((~e)&g);
      const temp1=(h+S1+ch+K[t]+w[t])>>>0;
      const S0=rotr(a,2)^rotr(a,13)^rotr(a,22);
      const maj=(a&b)^(a&c)^(b&c);
      const temp2=(S0+maj)>>>0;
      h=g;g=f;f=e;e=(d+temp1)>>>0;d=c;c=b;b=a;a=(temp1+temp2)>>>0;
    }
    h0=(h0+a)>>>0;h1=(h1+b)>>>0;h2=(h2+c)>>>0;h3=(h3+d)>>>0;h4=(h4+e)>>>0;h5=(h5+f)>>>0;h6=(h6+g)>>>0;h7=(h7+h)>>>0;
  }
  const out=[];
  [h0,h1,h2,h3,h4,h5,h6,h7].forEach(function(x){ out.push((x>>>24)&255,(x>>>16)&255,(x>>>8)&255,x&255); });
  return out;
}
function strToBytes(s){
  const bytes=[];
  for (let i=0;i<s.length;i++){
    let c=s.charCodeAt(i);
    if (c<0x80) bytes.push(c);
    else if (c<0x800){ bytes.push(0xc0|(c>>6),0x80|(c&0x3f)); }
    else if (c>=0xd800 && c<0xdc00){ const c2=s.charCodeAt(++i); const cp=0x10000+((c&0x3ff)<<10)+(c2&0x3ff); bytes.push(0xf0|(cp>>18),0x80|((cp>>12)&0x3f),0x80|((cp>>6)&0x3f),0x80|(cp&0x3f)); }
    else { bytes.push(0xe0|(c>>12),0x80|((c>>6)&0x3f),0x80|(c&0x3f)); }
  }
  return bytes;
}
function hmacSha256Hex(keyStr, msgStr){
  let key = strToBytes(keyStr);
  if (key.length>64) key = sha256(key);
  while (key.length<64) key.push(0);
  const ipad = key.map(function(b){ return b^0x36; });
  const opad = key.map(function(b){ return b^0x5c; });
  const inner = sha256(ipad.concat(strToBytes(msgStr)));
  const outer = sha256(opad.concat(inner));
  return outer.map(function(b){ return ('0'+b.toString(16)).slice(-2); }).join('');
}

const body = ($input.first().json.body) || {};
const event = body.event;

// 1) Проверка URL от Zoom (CRC)
if (event === 'endpoint.url_validation') {
  const plainToken = body.payload.plainToken;
  const encryptedToken = hmacSha256Hex(ZOOM_SECRET, plainToken);
  return [{ json: { isValidation: true, event: event, response: { plainToken: plainToken, encryptedToken: encryptedToken } } }];
}

// 2) Реальное событие (recording.completed): достаём аудио и готовим заливку в Fireflies
const obj = (body.payload && body.payload.object) || {};
const downloadToken = body.download_token || (body.payload && body.payload.download_token) || '';
const files = obj.recording_files || [];
let audio = null;
for (let i=0;i<files.length;i++){ if (files[i].file_type === 'M4A') { audio = files[i]; break; } }
if (!audio) { for (let i=0;i<files.length;i++){ if ((files[i].recording_type||'').indexOf('audio') >= 0) { audio = files[i]; break; } } }
let audioUrl = '';
if (audio && audio.download_url) {
  audioUrl = audio.download_url + (audio.download_url.indexOf('?') >= 0 ? '&' : '?') + 'access_token=' + downloadToken;
}
const startTime = obj.start_time || '';
const title = (obj.topic || 'Zoom Meeting') + ' — ' + (startTime ? startTime.slice(0,10) : '');

const firefliesBody = {
  query: 'mutation UploadAudio($input: AudioUploadInput) { uploadAudio(input: $input) { success title message } }',
  variables: { input: { url: audioUrl, title: title, custom_language: 'ru', client_reference_id: (obj.uuid || '') } }
};

return [{ json: {
  isValidation: false,
  event: event,
  response: {},
  meetingUuid: obj.uuid || '',
  topic: obj.topic || '',
  startTime: startTime,
  timezone: obj.timezone || '',
  audioUrl: audioUrl,
  audioFound: !!audioUrl,
  title: title,
  firefliesBody: firefliesBody
} }];
